from pathlib import Path
import json,shutil
B=Path(__file__).parent;R=B.parents[1];O=B/'site/dist';O.mkdir(parents=True,exist_ok=True)
research=json.loads((R/'outputs/integrated-research-20261024/统一研究数据.json').read_text());execution=json.loads((B/'执行依据与测算数据.json').read_text())
refs=json.loads((R/'outputs/integrated-research-20261024/报告引用来源.json').read_text())
data={k:research[k]for k in ['date','macro','cases','selection','market']};data['sources']=refs;data['execution']=execution
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>高端线下社群市场调研与对标</title><style>
:root{--ink:#243c49;--muted:#526871;--line:#d6dfdf;--paper:#f4f3ef;--gold:#987843}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.8 -apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif}header{background:var(--ink);color:#fff;padding:45px max(5vw,24px) 36px}header small{letter-spacing:2px;color:#dfc797}h1{font:500 clamp(28px,3.8vw,44px)/1.4 'Songti SC',serif;margin:16px 0}h2{font:600 27px/1.5 'Songti SC',serif;margin:28px 0 15px}h3{font-size:19px;line-height:1.5;margin:10px 0}p{margin:10px 0}nav{position:sticky;top:0;z-index:8;background:#f4f3eff7;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:14px;padding:12px 5vw}button,input,select{font:inherit}button,.button{border:1px solid #adbcbc;padding:8px 15px;background:#fff;color:var(--ink);border-radius:4px;cursor:pointer;text-decoration:none}button.active{background:var(--ink);color:white}a{color:#77562b;text-underline-offset:4px}main{max-width:1320px;margin:auto;padding:8px 5vw 50px}.page{display:none}.page.active{display:block}.lead{font-size:19px;max-width:970px}.note{font-size:14px;color:var(--muted)}header .note{color:#d3dfdf}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:26px 0}.stat,.card{background:white;border:1px solid var(--line);padding:22px}.stat strong{font:32px/1.4 Georgia,serif;color:var(--gold)}.stat span{display:block;font-size:14px}.filters{display:flex;flex-wrap:wrap;gap:9px;margin:22px 0}details{padding:20px 24px;background:#fff;border:1px solid var(--line);margin:15px 0}summary{cursor:pointer;font-size:20px;font-weight:600}summary small{font-size:13px;font-weight:400;color:var(--muted);margin-left:12px}.field{display:grid;grid-template-columns:130px 1fr;gap:16px;border-top:1px solid #e5eae9;padding:11px 0}.field b{font-weight:600}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:680px;background:white;margin:18px 0}th,td{text-align:left;vertical-align:top;padding:11px 14px;border-bottom:1px solid var(--line)}th{background:#e7edee}.smalltable td{font-size:14px}.search{padding:10px 14px;width:100%;max-width:550px;border:1px solid #aabbbc;border-radius:3px;background:white}.download{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}.modelinputs{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.modelinputs label{font-size:14px}.modelinputs input{display:block;width:100%;margin-top:5px;padding:8px 12px;background:#fff8e8;border:1px solid #c6beac;border-radius:3px}.modelout{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:18px 0}.modelout div{padding:18px;background:#e7eef0}.modelout strong{display:block;font-size:27px}.negative{color:#9e4b36}.sourcelist p{font-size:14px;overflow-wrap:anywhere}.pill{display:inline-block;padding:3px 9px;background:#edf1f0;margin:4px;font-size:13px}.gallery{display:flex;gap:12px;flex-wrap:wrap}.gallery a{display:block}footer{margin-top:35px;border-top:1px solid var(--line);padding-top:20px}.hidden{display:none}@media(max-width:800px){.stats,.modelinputs,.modelout{grid-template-columns:1fr 1fr}.field{grid-template-columns:1fr;gap:2px}main{padding:10px 18px 35px}header{padding:30px 20px}nav{padding:10px 18px;gap:9px}summary small{display:block;margin:5px 0}}@media(max-width:480px){.stats,.modelinputs,.modelout{grid-template-columns:1fr}nav .note{display:none}}
</style></head><body><header><small>GATSBY CLUB · PRIVATE RESEARCH</small><h1>高端线下社群市场调研与对标</h1><p class="lead">围绕同一批客户，持续组织商业交流、婚恋交友与社交旅行。</p><p class="note">2026年10月24日更新 · 先看市场，再看具体公司与产品 · A8及以上方向保留</p></header><nav><button class="active" data-page="market">第一部分 市场调研</button><button data-page="benchmark">第二部分 对标</button><span class="note">正式报告与Excel在页末下载</span></nav><main>
<section id="market" class="page active"><h2>市场规模与客户基础</h2><p>商业社交、婚恋服务和旅行分别看规模与付费形式；同一品牌的不同会籍按产品比较。</p><div class="stats"><div class="stat"><strong>10.6万户</strong><span>内地亿元总资产家庭</span><span>截至2025年1月1日 · 胡润估计</span></div><div class="stat"><strong>676.5万对</strong><span>2025年结婚登记</span><span>年度公报终值</span></div><div class="stat"><strong>65.22亿人次</strong><span>2025国内居民出游</span><span>文化和旅游部</span></div><div class="stat"><strong>6.30万亿元</strong><span>2025国内旅游花费</span><span>全国出游花费口径</span></div></div><p class="note">以上分别衡量财富人群、婚姻和旅游背景。高端线下社群目前缺少同口径行业总收入与前五收入，市场份额留空。</p><details><summary>展开统计定义与来源</summary><div id="macro"></div></details><h2>三个方向怎样收费</h2><div class="scroll"><table><thead><tr><th>方向</th><th>主要付费形式</th><th>本轮可核的例子</th></tr></thead><tbody><tr><td>商业社交</td><td>年费、活动票、教育项目</td><td>BoL 488／2888元年费；Founder Feast温哥华39.99加元月费，餐酒另付；长江2026级EMBA99.8万元／项目。</td></tr><tr><td>婚恋交友</td><td>单次活动、长期顾问、定制项目</td><td>Selected本次1688元展示价；钻石30万、60万、100万起的项目费。活动和顾问服务分开比较。</td></tr><tr><td>社交旅行</td><td>按团期收费，房型和机票另列</td><td>奇语济州“1k+”地面起价；OWR墨西哥城1400英镑，独住另225；心动计划同帖6280／7280起价有差异。</td></tr></tbody></table></div><h2>完整机构地图</h2><p class="note" id="mapCount"></p><input id="mapSearch" class="search" placeholder="搜索机构、客户、地区或研究用途" aria-label="搜索机构"><div class="scroll"><table class="smalltable"><thead><tr><th>机构</th><th>组织方式及地区</th><th>客户与定位</th><th>本轮用途</th><th>入口</th></tr></thead><tbody id="mapRows"></tbody></table></div></section>
<section id="benchmark" class="page"><h2>5家机构 6条产品线</h2><p class="lead">BoL商业与Selected婚恋分别展开；其他四家各负责一种明确的学习用途。成熟品牌与小规模可实施产品分层比较。</p><div class="filters" id="filters"></div><div id="caseRows"></div><details><summary>前轮候选为什么继续保留</summary><p>Hampton保留固定小组与年费机制；其创始人的播客资源不作为我们的起点。Flash Pack保留精品独行旅行，指定团期动态价尚缺。The Offline Club保留城市社群延伸度假的形式。FTLO日本九日6899美元起保留为精品地面报价参照。长江、EO、马会、木兰及国外九家继续在报告和机构地图中。</p><p>大超因个人IP依赖不列启动主对标；正和岛、优家荟按要求退出推荐。</p></details><details id="costTool"><summary>执行附录 住宿报价与旅行费用测算<small>依据新查到的同日期公开价更新，可改输入</small></summary><h3>先看真实的同日房型报价</h3><p>11月19日至22日，1人1房三晚。普通含早套餐7870元，含税；会员含早7478元，预付含早7240元。价格对应不同条款，未证明14间可同价。</p><div id="quoteRows"></div><h3>研究情景可调整</h3><p class="note">19800元沿用旧研究试价。酒店预算默认7870元，其余仍为预算；已含项目工时，未扣公司日常成本和税费。车辆按乘客位分批计费。</p><div class="modelinputs" id="inputs"></div><div class="modelout"><div>单团贡献<strong id="outContribution"></strong></div><div>保守周转金<strong id="outCash"></strong></div><div>财务保本人数<strong id="outBreak"></strong></div></div><p id="outDetail"></p><p class="note">周转金按酒店含税全价预留、其余交付及车辆70%预付、客户首款30%测算。页面酒店预付款6750元，其他税费支付时点未单列。财务保本与12人的产品人数下限分别判断。</p><h3>两场活动及一条旅行初案</h3><div id="launchCards"></div></details></section>
<footer><h2>统一材料下载</h2><div class="download"><a class="button" href="research.pdf" target="_blank">正式报告 PDF</a><a class="button" href="research.xlsx">市场调研与对标总Excel</a><a class="button" href="launch.xlsx">启动产品与费用测算</a><a class="button" href="meeting.docx">合伙人讨论稿</a></div><details><summary>BoL小程序实查截图</summary><p>微信搜索BoL万象博联，再进入VIP及Selected活动。以下为本机留存截图。</p><div class="gallery" id="bolGallery"></div></details><details><summary>原始资料入口</summary><div id="sources" class="sourcelist"></div></details><p class="note">本机私有讨论资料。供应商团体书面报价、真实客户访谈和资源确认仍按分工补齐；研究试价未变成对外承诺。</p></footer></main><script>const DATA=__DATA__;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=v=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(v)+'元';
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===b.dataset.page));}));
$('#macro').innerHTML=DATA.macro.map(r=>`<div class="field"><b>${esc(r[1])}</b><span>${r[2]===null?'未取得统一口径':esc(r[2])+' '+esc(r[3])}<br>${esc(r[4])}；${esc(r[5])}</span></div>`).join('');
function map(){let q=$('#mapSearch').value.trim().toLowerCase(),rows=DATA.market.filter(r=>r.join(' ').toLowerCase().includes(q));$('#mapCount').textContent=`完整名录${DATA.market.length}家，当前显示${rows.length}家；名录覆盖不等于同等深访。`;$('#mapRows').innerHTML=rows.map(r=>`<tr><td>${esc(r[0])}</td><td>${esc(r[1])}<br>${esc(r[2])}</td><td>${esc(r[3])}</td><td>${esc(r[4])}</td><td>${r[5]?`<a href="${esc(r[5])}" target="_blank" rel="noopener">原文</a>`:'微信小程序'}</td></tr>`).join('');}$('#mapSearch').addEventListener('input',map);map();
const field=(a,b)=>`<div class="field"><b>${esc(a)}</b><div>${b}</div></div>`;
function cases(group='全部'){let c=DATA.cases.filter(x=>group==='全部'||x.group===group);$('#caseRows').innerHTML=c.map(x=>`<details><summary>${esc(x.name)}<small>${esc(x.group)} · ${esc(x.role)}</small></summary><p>${esc(x.what)}</p><h3>收费与权益</h3>${x.fees.map(r=>field(r[0],'<strong>'+esc(r[1])+'</strong><br>'+esc(r[2]))).join('')}<h3>客户画像</h3>${x.people.map(r=>field(r[0],esc(r[1]))).join('')}<h3>活动与服务流程</h3>${x.flow.map((v,i)=>'<p>'+String(i+1)+' '+esc(v)+'</p>').join('')}<h3>客户从哪里来</h3><p>${esc(x.acquisition)}</p><h3>经营表现</h3><p>${esc(x.performance)}</p><h3>研究判断</h3><p>${esc(x.judgment)}</p></details>`).join('');}
$('#filters').innerHTML=['全部','商业社交','婚恋交友','社交旅行'].map((v,i)=>`<button data-group="${v}" class="${i?'':'active'}">${v}</button>`).join('');document.querySelectorAll('[data-group]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-group]').forEach(x=>x.classList.toggle('active',x===b));cases(b.dataset.group);}));cases();
$('#quoteRows').innerHTML=DATA.execution.quotes.filter(x=>['SR-PRE','SR-FLEX','SR-BB'].includes(x.id)).map(x=>`<div class="field"><b>${esc(x.rate_name)}<br>${money(x.total)}</b><span>${esc(x.breakfast)}<br>${esc(x.cancellation)}<br><a href="${esc(x.source_url)}" target="_blank" rel="noopener">官网查询入口</a></span></div>`).join('');
const controls=[['price','研究试价 元／人',19800],['n','付费人数',14],['hotel','每人三晚住宿预算',7870],['other','每人其他直接交付',3500],['cac','每人获客预算',1200],['fixed','固定交付及工时预算',48000],['vehicle','每批车辆全程预算',9800],['seats','每批乘客位 不含司机',19],['staff','现场岗位人数',3],['refund','退款金额比例 %',3],['deposit','客户首付款比例 %',30]];
$('#inputs').innerHTML=controls.map(([id,label,v])=>`<label>${label}<input id="input-${id}" type="number" value="${v}" min="0" ${['n','seats','staff'].includes(id)?'step="1"':'step="any"'} aria-label="${label}"></label>`).join('');
function calc(){let a={};controls.forEach(([id])=>{let t=$('#input-'+id).value;a[id]=t===''?NaN:Number(t);});if(Object.values(a).some(v=>!Number.isFinite(v))||a.n<1||a.price<=0||a.hotel<=0||a.seats<1||a.refund>100||a.deposit>100){['#outContribution','#outCash','#outBreak'].forEach(id=>$(id).textContent='请补有效输入');$('#outDetail').textContent='人数、房价及车辆乘客位需大于0；比例在0—100%之间。';return;}let r=a.refund/100,g=a.price*a.n,v=Math.ceil((a.n+a.staff)/a.seats)*a.vehicle,cost=(a.hotel+a.other+a.cac)*a.n+a.fixed+v,con=g*(1-r)-cost,due=a.hotel*a.n+.7*a.other*a.n+.7*v+a.fixed+a.cac*a.n,cash=Math.max(.4*a.fixed+a.cac*a.n,due-g*a.deposit/100,0)+g*r;let be=null;for(let n=1;n<=16;n++){let margin=a.price*n*(1-r)-(a.hotel+a.other+a.cac)*n-a.fixed-Math.ceil((n+a.staff)/a.seats)*a.vehicle;if(margin>=0){be=n;break;}}$('#outContribution').textContent=money(con);$('#outContribution').classList.toggle('negative',con<0);$('#outCash').textContent=money(cash);$('#outBreak').textContent=be===null?'16人内未保本':be+'人';$('#outDetail').textContent=`收款${money(g)}；直接交付${money((a.hotel+a.other)*a.n)}；车辆${money(v)}（${Math.ceil((a.n+a.staff)/a.seats)}批）；获客${money(a.cac*a.n)}；固定及工时${money(a.fixed)}。${a.n<12?'低于12人的产品人数下限。':'达到12人的产品人数下限，仍需审核报名结构。'}`;}
document.querySelectorAll('#inputs input').forEach(e=>e.addEventListener('input',calc));calc();
$('#launchCards').innerHTML=DATA.execution.models.map(x=>`<details><summary>${esc(x.name)}<small>研究试价${x.price}元／人</small></summary>${field('客户与第一次付费',esc(x.customer)+'<br>'+esc(x.reason))}${field('包含',esc(x.rights))}${field('交付',x.flow.map(t=>'<p>'+esc(t)+'</p>').join(''))}${field('团队与再次参加',esc(x.team)+'<br>'+esc(x.retention))}</details>`).join('');
$('#sources').innerHTML=DATA.sources.map(x=>`<p>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.id+' '+x.name)}</a>`:esc(x.id+' '+x.name+' 微信小程序内查看')}<br>${esc(x.period)}；${esc(x.kind)}</p>`).join('');
$('#bolGallery').innerHTML=[['vip-starlight-488.png','星光会籍'],['vip-2888-network-salon.png','星辰酒会与沙龙'],['selected-20261024-admission.png','Selected准入'],['selected-20261024-flow.png','Selected流程']].map(([name,label])=>`<a href="bol/${name}" target="_blank">${label}截图</a>`).join('');
</script></body></html>'''
html=html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<'+chr(92)+'/'))
(O/'index.html').write_text(html);(O/'研究讨论网站.html').write_text(html)
for source,target in [(R/'outputs/integrated-research-20261024/交付文件/高端线下社群市场调研与对标报告.pdf','research.pdf'),(R/'outputs/integrated-research-20261024/交付文件/高端线下社群市场调研与对标总表.xlsx','research.xlsx'),(B/'交付文件/启动产品与费用测算.xlsx','launch.xlsx')]:
 if source.exists():shutil.copy2(source,O/target)
(O/'bol').mkdir(exist_ok=True)
for name in ['vip-starlight-488.png','vip-2888-network-salon.png','selected-20261024-admission.png','selected-20261024-flow.png']:shutil.copy2(R/'.research-private/bol-research-20261024'/name,O/'bol'/name)
meeting=B/'交付文件/高端线下社群合伙人会议讲解稿.docx'
if meeting.exists():shutil.copy2(meeting,O/'meeting.docx')
(B/'网站数据.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
print('Website built',O)
